<script setup lang="ts">
import { computed } from 'vue'

const props = defineProps<{
  labId: string
  customClass?: string
}>()

const normalizedLab = computed(() => {
  const s = props.labId.toLowerCase()
  if (s.includes('alibaba') || s.includes('qwen')) return 'alibaba'
  if (s.includes('openai') || s.includes('gpt')) return 'openai'
  if (s.includes('anthropic') || s.includes('claude')) return 'anthropic'
  if (s.includes('deepseek')) return 'deepseek'
  if (s.includes('google') || s.includes('gemini') || s.includes('gemma')) return 'google'
  if (s.includes('meta') || s.includes('llama')) return 'meta'
  if (s.includes('moonshot') || s.includes('kimi')) return 'moonshotai'
  if (s.includes('mistral') || s.includes('codestral')) return 'mistral'
  if (s.includes('nvidia') || s.includes('nemotron')) return 'nvidia'
  if (s.includes('cohere')) return 'cohere'
  if (s.includes('minimax')) return 'minimax'
  if (s.includes('tencent') || s.includes('hunyuan')) return 'tencent'
  if (s.includes('perplexity') || s.includes('sonar')) return 'perplexity'
  return s
})
</script>
